{
  "schemaVersion": 1, "id": "shell-kit", "version": "0.1.0",
  "description": "Host POSIX shell, used privately for package preparation unless explicitly requested",
  "host": { "os": ["linux"], "arch": ["x64", "arm64"] },
  "preparation": { "granularity": "capability" },
  "permissions": { "filesystem": "package-state-and-workspace", "network": false },
  "provides": [{
    "id": "shell.execute", "interfaceVersion": 1, "kind": "tools", "description": "Run a trusted shell command",
    "tools": [{ "name": "shell_run", "description": "Execute an authorized shell command in the workspace. Not a sandbox.", "exposure": "on_activation",
      "parameters": { "type": "object", "properties": { "command": { "type": "string" } }, "required": ["command"], "additionalProperties": false }
    }]
  }],
  "requires": [],
  "lifecycle": { "runtime": "node", "entry": "worker.mjs" }
}

import { spawnSync } from 'node:child_process';
import { rm } from 'node:fs/promises';
let text = '';
for await (const chunk of process.stdin) text += chunk;
const request = JSON.parse(text);
const run = command => spawnSync('sh', ['-c', command], { cwd: request.workspace, env: process.env, encoding: 'utf8', timeout: 10000, maxBuffer: 32768 });
let response;
switch (request.operation) {
  case 'check': {
    const found = run('command -v sh');
    const passed = found.status === 0 && found.stdout.trim().length > 0;
    response = { capabilities: { 'shell.execute': { status: passed ? 'ready' : 'blocked',
      checks: [{ name: 'host_shell', passed }], ...(passed ? { resources: { shell: found.stdout.trim() } } : { reason: 'Host POSIX shell missing' }) } } };
    break;
  }
  case 'prepare': throw new Error('Host shell must already exist; cannot bootstrap itself');
  case 'invoke': {
    if (request.tool !== 'shell_run') throw new Error('Unknown tool');
    const output = run(request.args.command);
    if (output.error || output.status !== 0) throw new Error(`Shell failed: ${output.error?.message ?? output.stderr}`);
    response = { stdout: output.stdout, stderr: output.stderr, exitCode: output.status }; break;
  }
  case 'release': await rm(request.taskDir, { recursive: true, force: true }); response = { released: true }; break;
  default: throw new Error('Unknown operation');
}
process.stdout.write(JSON.stringify(response));
